@lru_cache(maxsize=3)
def _mapped_requests(raw, expected):
    return NativeRequestsImage(raw, expected)


def installed_requests(manifest_path, *, capture_identity=False):
    """Fresh admission; later execution retains this actual immutable mapping.

    An active worker bundle is authoritative. The cache shares only immutable
    executable bytes, never an admission decision or a mutable file snapshot.
    Each returned checker capability owns its exact source/manifest bytes.
    """
    from .hia_native_helpers import pinned_image
    selected = pinned_image(manifest_path, SOURCE, SCHEMA, NativeRequestsImage)
    path = Path(manifest_path).resolve(strict=True)
    raw = _regular_bytes(path, 16384)
    value = json.loads(raw, object_pairs_hook=_manifest_pairs)
    fields = {'schema', 'source_sha256', 'image_path', 'image_sha256', 'compiler_sha256'}
    if (type(value) is not dict or set(value) != fields or value['schema'] != SCHEMA
            or any(type(value[key]) is not str or len(value[key]) != 64
                   or any(char not in '0123456789abcdef' for char in value[key])
                   for key in ('source_sha256', 'image_sha256', 'compiler_sha256'))):
        raise ValueError('invalid service-requests manifest')
    name = value['image_path']
    if (type(name) is not str or not name or name in ('.', '..')
            or any(ord(char) < 32 for char in name) or Path(name).name != name):
        raise ValueError('service-requests image must be a sibling basename')
    source_raw = _regular_bytes(SOURCE, 8 << 20)
    if sha256(source_raw).hexdigest() != value['source_sha256']:
        raise ValueError('service-requests source identity mismatch')
    image_path = path.parent / name
    image_raw = _regular_bytes(image_path, 1 << 20)
    if sha256(image_raw).hexdigest() != value['image_sha256']:
        raise ValueError('service-requests image identity mismatch')
    if selected is None:
        selected = _mapped_requests(image_raw, value['image_sha256'])
    elif type(selected) is not NativeRequestsImage or selected.image_sha256 != value['image_sha256']:
        raise ValueError('service-requests mapping differs from its pinned worker image')
    if (_regular_bytes(path, 16384) != raw or _regular_bytes(SOURCE, 8 << 20) != source_raw
            or _regular_bytes(image_path, 1 << 20) != image_raw):
        raise ValueError('service-requests selection changed during admission')
    if capture_identity:
        from .hia_checker_identity import hold_native_owner
        return hold_native_owner(SELECTOR, selected, raw, source_raw)
    return selected


def admitted_requests(*, capture_identity=False):
    selected = os.environ.get(SELECTOR)
    if not selected:
        return None
    return installed_requests(selected, capture_identity=capture_identity)


def _match_exception(frame, slot):
    # This invokes the interpreter's real exception matching, not isinstance
    # (which has different metaclass behavior and accepts non-exception types).
    # No borrowed error or match type is saved in a transport named local.
    try:
        frame.image._delivery.deliver(frame.error)
    except frame._get(slot) as delivered:
        if delivered is not frame.error:
            frame._uncertain = True
            raise
        return 1
    except BaseException as delivered:
        if delivered is not frame.error:
            frame._uncertain = True
            raise
        return 0
    frame._uncertain = True
    raise RequestsUnknown('requests exception delivery returned')


class RequestsFrame(PlanFrame):
    def __init__(self, *args, **kwargs):
        self._region_child = None
        self._region_value = _EMPTY
        self._region_returned = False
        super().__init__(*args, **kwargs)

    def _global(self, name):
        namespace = self.image.namespace
        if name in namespace:
            return namespace[name]
        if name in vars(builtins):
            return vars(builtins)[name]
        raise NameError("name '" + name + "' is not defined", name=name)

    def _move(self, slot):
        value = self._get(slot)
        self._clear(slot)
        return value

    def _load_named(self, slot, name, role):
        if type(slot) is not int or not 0 <= slot < len(self.values):
            raise RequestsUnknown('requests named slot is outside its frame')
        value = self.values[slot]
        if slot in self.cells:
            value = value.value
        if value is _EMPTY:
            return self.image.foreign.unbound(name, role)
        return value

    def _call(self, args, raw):
        if raw == (0, 251):
            if args:
                raise RequestsUnknown('request re-raise operands differ')
            raise
        if raw == (0, 253):
            if len(args) != 2 or type(self._get(args[0])) is not dict:
                raise RequestsUnknown('requests dictionary-update ABI differs')
            return self.image.foreign.update_dict(self, args[0], args[1])
        if raw in ((0, 254), (1, 254)):
            if len(args) != 3 + raw[0] or type(self._get(args[1])) is not tuple:
                raise RequestsUnknown('requests mapping-prepare ABI differs')
            if raw[0] == 0:
                return self.image.foreign.merge_empty(self, *args)
            return self.image.foreign.merge_kind(self, *args)
        if raw == (0, 255):
            if len(args) != 3:
                raise RequestsUnknown('requests mapping-call ABI differs')
            return self.image.foreign.mapping_call(self, *args)
        if len(raw) < 2 or len(raw) != 2 + raw[1] or len(args) != 1 + raw[0] + raw[1]:
            raise RequestsUnknown('requests ordinary-call ABI differs')
        key = (raw[0], tuple(self.image.literal(index) for index in raw[2:]))
        call = self.image.foreign.CALLS.get(key)
        if call is None:
            raise RequestsUnknown('requests call shape is outside the fixed policy')
        return call(self, args)

    def _function(self, args, raw, vector):
        if len(raw) != 2:
            raise RequestsUnknown('requests closure representation differs')
        mode, generator = raw
        if generator not in (0, 1) or len(args) != generator:
            raise RequestsUnknown('requests closure entry representation differs')
        layout = self.image.layouts.get(mode)
        if layout is None or (layout[1] == 'generator') != bool(generator):
            raise RequestsUnknown('requests closure mode differs')
        captures = tuple(self.values[slot] for slot in vector)
        if len(captures) != layout[4] or any(type(cell) is not _Cell for cell in captures):
            raise RequestsUnknown('requests captured a non-cell or wrong closure')
        if generator:
            frame = RequestsFrame(self.image, mode, (self._get(args[0]),), captures,
                                    witness=self.witness)
            def native_generator():
                value = None
                try:
                    while True:
                        value = None
                        if frame.drive() == 0:
                            return
                        value = frame.take(yielded=True)
                        yield value
                finally:
                    value = None
            return native_generator()
        image, witness = self.image, self.witness
        def native_function(*arguments):
            frame = RequestsFrame(image, mode, arguments, captures, witness=witness)
            arguments = None
            return image.finish(frame)
        return native_function

    def _drive_region(self,mode,vector):
        captures=tuple(self.values[slot] for slot in vector)
        if any(type(cell) is not _Cell for cell in captures):
            raise RequestsUnknown('service-requests with region captured a non-cell')
        child=RequestsFrame(self.image,mode,(),captures,witness=self.witness)
        self._region_child=child
        captures=None
        child.handled=self.handled
        self._region_value=self.image.finish(child)
        if type(self._region_value) is not tuple or len(self._region_value)!=2:
            self._uncertain=True
            raise RequestsUnknown('service-requests region lacks its HIA terminal record')
        self._region_returned=True

    def _with_region(self,manager,mode,target,vector):
        if self._region_child is not None or self._region_value is not _EMPTY:
            self._uncertain=True
            raise RequestsUnknown('service-requests context-manager port is reentered')
        self._region_returned=False
        try:
            if target==65535:
                with self._move(manager):
                    self._drive_region(mode,vector)
            else:
                with self._move(manager) as entered:
                    self._set(target,entered)
                    entered=None
                    self._drive_region(mode,vector)
            child=self._region_child
            if (child is None or child._uncertain or not child.closed
                    or not child._terminal_taken or child.pending is not None):
                self._uncertain=True
                raise RequestsUnknown('context manager suppressed an unconfirmed HIA body')
            if self._region_returned:
                if child._status!=5 or not child._retired:
                    self._uncertain=True
                    raise RequestsUnknown('context manager returned a non-successful HIA body')
                return self._region_value,1
            if child._status!=3:
                self._uncertain=True
                raise RequestsUnknown('context manager has no confirmed suppressed exception')
            return None,0
        finally:
            child=self._region_child
            if self._uncertain or (child is not None and child._uncertain):
                self._uncertain=True
                _WITH_UNKNOWN[self.nonce]=self
            else:
                self._region_value=_EMPTY
                self._region_child=None


    def _effect(self):
        op, destinations, args, raw, vector = self._parts()
        if op == 14 and raw:
            if len(raw) != 2 or raw[0] != 1 or len(args) != 2 or destinations or vector:
                raise RequestsUnknown('requests attribute-store representation differs')
            setattr(self._get(args[0]), self.image.literal(raw[1]), self._get(args[1]))
            return 0
        if op == 9 and len(raw) == 3 and raw[1] == 250:
            if len(args) != 1 or len(destinations) != 1:
                raise RequestsUnknown('requests with-region representation differs')
            result, flag = self._with_region(args[0], raw[0], raw[2], vector)
            self._set(destinations[0], (flag, result))
            result = None
            return 0
        if op == 13 and raw == (4,):
            if len(destinations) != 4 or len(args) != 1 or vector:
                raise RequestsUnknown('requests four-value unpack representation differs')
            first, second, third, fourth = self._get(args[0])
            self._set(destinations[0], first)
            self._set(destinations[1], second)
            self._set(destinations[2], third)
            self._set(destinations[3], fourth)
            first = second = third = fourth = None
            return 0
        if op == 19:
            if len(raw) < 2 or len(destinations) != 1 or vector:
                raise RequestsUnknown('requests import representation differs')
            if raw[0] == 0 and not args:
                module = self.image.literal(raw[1])
                names = tuple(self.image.literal(index) for index in raw[2:])
                if module not in _IMPORTS or any(name not in _IMPORTS[module] for name in names):
                    raise RequestsUnknown('requests import is outside fixed ports')
                port = self.image._import_names.get((module, names))
                if port is None:
                    raise RequestsUnknown('requests import group differs')
                self._set(destinations[0], port())
            elif raw[0] == 1 and len(raw) == 2 and len(args) == 1:
                name = self.image.literal(raw[1])
                port = self.image._import_from.get(name)
                if port is None:
                    raise RequestsUnknown('requests imported field differs')
                self._set(destinations[0], port(self._get(args[0])))
            else:
                raise RequestsUnknown('requests import phase differs')
            return 0
        if op == 15 and raw:
            if len(raw) != 2 or len(args) != 1 or len(destinations) != 1 or vector:
                raise RequestsUnknown('requests named-load representation differs')
            self._set(destinations[0], self._load_named(args[0], self.image.literal(raw[0]), raw[1]))
            return 0
        if op == 21:
            if len(args) != 1 or destinations or raw or vector:
                raise RequestsUnknown('requests exception matcher representation differs')
            return _match_exception(self, args[0])
        return super()._effect()

    def service(self, issued):
        # Same issued-object/native-preclaim protocol as the frozen Plan
        # engine. The additional flag prevents a failing physical exception
        # mechanism from being acknowledged as a known foreign policy error.
        if (self.closed and not self._retiring) or issued is not self.pending or type(issued) is not Issued:
            raise RequestsUnknown('requests observation is not the issued permission')
        if type(issued.raw) is not bytes or issued.raw != self.frame_bytes or self.executed:
            raise RequestsUnknown('requests observation changed or was consumed')
        self.executed = True
        try:
            if self._invoke(2, op=_read_word(issued.raw, 32)) != 4:
                raise RequestsUnknown('requests observation claim refused')
            observed = _capture_with_handler(self)
            if self._uncertain:
                if not observed[0]:
                    raise observed[1]
                raise RequestsUnknown('requests physical effect lost its outcome')
            if observed[0]:
                self.reply = (observed[1], 0)
            else:
                self.error = observed[1]
                self.reply = (0, 1)
            observed = None
            self.completed = True
        except BaseException:
            self._uncertain = True
            self.close(release=False)
            raise


class NativeRequestsImage(NativeMachinePlanControl):
    def __init__(self, image, expected_sha256, namespace=None):
        try:
            super().__init__(image, expected_sha256)
            self._bind_namespace(namespace)
        except BaseException:
            self._entry = None
            for resource in (getattr(self, '_delivery', None), getattr(self, '_mapping', None)):
                if resource is not None:
                    try:
                        resource.close()
                    except BaseException:
                        _UNCONFIRMED_IMAGE_CLEANUP.append((self, resource))
            raise

    def literal(self, index):
        if type(index) is not int or not 0 <= index < self._literal_count:
            raise RequestsUnknown('requests scalar literal index differs')
        if index not in self._literals:
            at = struct.unpack_from('<I', self.table, self._literal_offsets + 4 * index)[0]
            kind, size = struct.unpack_from('<BQ', self.table, at)
            if kind in (5, 6):
                if at + 9 + size > len(self.table) or kind == 6 and size != 8:
                    raise RequestsUnknown('requests scalar literal extent differs')
                raw = self.table[at + 9:at + 9 + size]
                self._literals[index] = raw if kind == 5 else struct.unpack('<d', raw)[0]
        if index in self._literals:
            return self._literals[index]
        return super().literal(index)

    def _bind_namespace(self, namespace):
        # Fixed CPython representation ports are admitted only when an actual
        # native image is selected. Default service imports retain the public
        # package's Python 3.11 support and do not run a 3.12+ ABI template.
        from . import hia_service_requests_foreign
        self.foreign = hia_service_requests_foreign
        if sha256(self.table).hexdigest() != self.foreign.TABLE_SHA256:
            raise RequestsUnknown('complete request HIA policy table differs')
        from . import hia_agent_service
        if namespace is None:
            namespace = vars(hia_agent_service)
        if type(namespace) is not dict:
            raise TypeError('requests requires the actual service global namespace')
        self.namespace = namespace
        self._import_names, self._import_from = self.foreign.import_ports(namespace)
        self.modes = {name: (number, arity) for number, (name, arity) in enumerate(ARITIES.items(), 1)}
        self.layouts = {}
        if type(self.foreign.FUNCTION_LAYOUT) is not tuple or len(self.foreign.FUNCTION_LAYOUT) != self.function_count:
            raise RequestsUnknown('complete requests function inventory differs')
        for expected, item in enumerate(self.foreign.FUNCTION_LAYOUT, 1):
            if (type(item) is not tuple or len(item) != 5 or item[0] != expected
                    or type(item[0]) is not int or item[1] not in ('function', 'lambda', 'generator', 'with_region')
                    or any(type(value) is not int or value < 0 for value in item[2:])):
                raise RequestsUnknown('requests lexical layout is not canonical')
            mode, kind, slots, arity, captures = item
            entry, actual_slots, info, metadata = self.function(mode)
            expected_info = arity | ((kind == 'generator') << 16) | (captures << 32)
            if slots != actual_slots or info != expected_info:
                raise RequestsUnknown('requests HIA lexical layout differs from the fixed bridge')
            self.layouts[mode] = item
        for mode, arity in self.modes.values():
            if self.function(mode)[2] != arity:
                raise RequestsUnknown('requests public method argument representation differs')
    def prepare(self, name, arguments, captures=(), *, witness=None):
        if type(name) is str:
            mode, arity = self.modes[name]
            if type(arguments) is not tuple or len(arguments) != arity or captures:
                raise RequestsUnknown('requests bound argument count differs')
        else:
            mode = name
        return RequestsFrame(self, mode, arguments, captures, witness=witness)

    def run(self, name, *arguments):
        frame = self.prepare(name, arguments)
        arguments = None
        return self.finish(frame)


class NativeRequestsService:
    """An immutable held image/custody scope; no Python reference to service."""
    def __init__(self, image, *, checker_custody=None):
        if type(image) is not NativeRequestsImage:
            raise TypeError('requests service requires its actual admitted image')
        self.image, self.custody, self.closed = image, checker_custody, False

    def checker_owner(self):
        if self.custody is None:
            raise RequestsUnknown('requests owner lacks actual captured checker custody')
        return self.custody

    def prepare(self, name, arguments):
        if self.closed:
            raise RequestsUnknown('requests service is closed for new work')
        return self.image.prepare(name, arguments)

    def finish(self, frame):
        if self.closed:
            raise RequestsUnknown('requests service is closed for new work')
        token = _ACTIVE.set(self)
        try:
            return self.image.finish(frame)
        finally:
            _ACTIVE.reset(token)


def active_requests():
    return _ACTIVE.get()

"""HIA-owned Agent verification coordination with fixed object/effect ports.

The image emits its complete immutable control program and chooses every
policy branch, object operation, once-only effect and retirement. Python holds
actual foreign objects; it does not import or interpret the policy authoring
source and never calls the seven retained reference bodies on this route.
Proof engines, proof-contract construction, storage, and native build/runtime
providers are separate declared dependencies, not claimed migrated here.
"""
from __future__ import annotations

import builtins
from contextvars import ContextVar
from functools import lru_cache
from hashlib import sha256
import json
import os
from pathlib import Path
import stat
import struct
import sys

from .hia_json_preflight_native import _source_resource_path
from .hia_machine_plan_control_native import (
    PlanFrame, NativeMachinePlanControl, _Cell, _EMPTY,
    Issued, _read_word, _capture_with_handler)
# A default import must not admit a selected-only CPython ABI. Keep the
# original mutable global binding: only its untouched initial sentinel loads.
_FOREIGN_NOT_LOADED = object()
_FOREIGN_MODULE_NAMESPACE = globals()
foreign = _FOREIGN_NOT_LOADED


def _load_foreign_ports():
    global foreign
    if _FOREIGN_MODULE_NAMESPACE.get('foreign') is _FOREIGN_NOT_LOADED:
        from . import hia_service_verification_foreign as foreign

SOURCE = _source_resource_path('examples/hia_bootstrap/service_verification.hepta')
SCHEMA = 'hepta.hia.service-verification-native.v1'
SELECTOR = 'HEPTA_HIA_SERVICE_VERIFICATION_MANIFEST'
ARITIES = {
    '_subject': 4, '_hia_verify': 2, '_verification': 5,
    '_replay_verification': 4, '_required_claims': 6,
    '_check_native_refinement_evidence': 6, '_native_refinement_binding': 5,
}
_ACTIVE = ContextVar('hia_service_verification_owner', default=None)
_UNCONFIRMED_IMAGE_CLEANUP = []


class VerificationUnknown(RuntimeError):
    """A native/effect handoff is unconfirmed; no permission is recreated."""


def _manifest_pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError('duplicate service-verification manifest field')
        result[key] = value
    return result


def _regular_bytes(path, limit):
    descriptor = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(descriptor, 'rb') as stream:
        before = os.fstat(stream.fileno())
        if not stat.S_ISREG(before.st_mode) or not 0 < before.st_size <= limit:
            raise ValueError('service-verification input must be a bounded ordinary file')
        raw = stream.read(limit + 1)
        after = os.fstat(stream.fileno())
    fields = ('st_dev', 'st_ino', 'st_size', 'st_mtime_ns', 'st_ctime_ns')
    if len(raw) != before.st_size or any(getattr(before, key) != getattr(after, key) for key in fields):
        raise ValueError('service-verification input changed while being read')
    return raw


@lru_cache(maxsize=3)
def _mapped_verification(raw, expected):
    return NativeVerificationImage(raw, expected)


def installed_verification(manifest_path, *, capture_identity=False):
    """Fresh admission; later execution retains this actual immutable mapping.

    An active worker bundle is authoritative. The cache shares only immutable
    executable bytes, never an admission decision or a mutable file snapshot.
    Each returned checker capability owns its exact source/manifest bytes.
    """
    from .hia_native_helpers import pinned_image
    selected = pinned_image(manifest_path, SOURCE, SCHEMA, NativeVerificationImage)
    path = Path(manifest_path).resolve(strict=True)
    raw = _regular_bytes(path, 16384)
    value = json.loads(raw, object_pairs_hook=_manifest_pairs)
    fields = {'schema', 'source_sha256', 'image_path', 'image_sha256', 'compiler_sha256'}
    if (type(value) is not dict or set(value) != fields or value['schema'] != SCHEMA
            or any(type(value[key]) is not str or len(value[key]) != 64
                   or any(char not in '0123456789abcdef' for char in value[key])
                   for key in ('source_sha256', 'image_sha256', 'compiler_sha256'))):
        raise ValueError('invalid service-verification manifest')
    name = value['image_path']
    if (type(name) is not str or not name or name in ('.', '..')
            or any(ord(char) < 32 for char in name) or Path(name).name != name):
        raise ValueError('service-verification image must be a sibling basename')
    source_raw = _regular_bytes(SOURCE, 8 << 20)
    if sha256(source_raw).hexdigest() != value['source_sha256']:
        raise ValueError('service-verification source identity mismatch')
    image_path = path.parent / name
    image_raw = _regular_bytes(image_path, 1 << 20)
    if sha256(image_raw).hexdigest() != value['image_sha256']:
        raise ValueError('service-verification image identity mismatch')
    if selected is None:
        selected = _mapped_verification(image_raw, value['image_sha256'])
    elif type(selected) is not NativeVerificationImage or selected.image_sha256 != value['image_sha256']:
        raise ValueError('service-verification mapping differs from its pinned worker image')
    if (_regular_bytes(path, 16384) != raw or _regular_bytes(SOURCE, 8 << 20) != source_raw
            or _regular_bytes(image_path, 1 << 20) != image_raw):
        raise ValueError('service-verification selection changed during admission')
    if capture_identity:
        from .hia_checker_identity import hold_native_owner
        return hold_native_owner(SELECTOR, selected, raw, source_raw)
    return selected


def admitted_verification(*, capture_identity=False):
    selected = os.environ.get(SELECTOR)
    if not selected:
        return None
    return installed_verification(selected, capture_identity=capture_identity)


def _match_exception(frame, slot):
    # This invokes the interpreter's real exception matching, not isinstance
    # (which has different metaclass behavior and accepts non-exception types).
    # No borrowed error or match type is saved in a transport named local.
    try:
        frame.image._delivery.deliver(frame.error)
    except frame._get(slot) as delivered:
        if delivered is not frame.error:
            frame._uncertain = True
            raise
        return 1
    except BaseException as delivered:
        if delivered is not frame.error:
            frame._uncertain = True
            raise
        return 0
    frame._uncertain = True
    raise VerificationUnknown('verification exception delivery returned')


class VerificationFrame(PlanFrame):
    def _global(self, name):
        namespace = self.image.namespace
        if name in namespace:
            return namespace[name]
        if name in vars(builtins):
            return vars(builtins)[name]
        raise NameError("name '" + name + "' is not defined", name=name)

    def _move(self, slot):
        # Only a separately native-claimed CALL may reach this fixed move.
        # Original stack operands now belong to CPython's actual CALL stack,
        # so a callee error traceback cannot extend their lifetime via slots.
        value = self._get(slot)
        self._clear(slot)
        return value

    def _call(self, args, raw):
        if raw == (0, 253):
            if len(args) != 2 or type(self._get(args[0])) is not dict:
                raise VerificationUnknown('verification dictionary-update ABI differs')
            return foreign.update_dict(self, args[0], args[1])
        if raw in ((0, 254), (1, 254)):
            if len(args) != 3 + raw[0] or type(self._get(args[1])) is not tuple:
                raise VerificationUnknown('verification mapping-prepare ABI differs')
            if raw[0] == 0:
                return foreign.merge_empty(self, *args)
            return foreign.merge_kind(self, *args)
        if raw == (0, 255):
            if len(args) != 3:
                raise VerificationUnknown('verification mapping-call ABI differs')
            return foreign.mapping_call(self, *args)
        if len(raw) < 2 or len(raw) != 2 + raw[1] or len(args) != 1 + raw[0] + raw[1]:
            raise VerificationUnknown('verification ordinary-call ABI differs')
        key = (raw[0], tuple(self.image.literal(index) for index in raw[2:]))
        call = foreign.CALLS.get(key)
        if call is None:
            raise VerificationUnknown('verification call shape is outside the fixed policy')
        return call(self, args)

    def _function(self, args, raw, vector):
        mode, generator = raw
        if generator != 1 or len(args) != 1:
            raise VerificationUnknown('verification lazy-frame ABI differs')
        captures = tuple(self.values[slot] for slot in vector)
        if any(type(cell) is not _Cell for cell in captures):
            raise VerificationUnknown('verification captured a non-cell')
        frame = VerificationFrame(self.image, mode, (self._get(args[0]),), captures,
                                  witness=self.witness)
        def native_generator():
            value = None
            try:
                while True:
                    value = None
                    if frame.drive() == 0:
                        return
                    value = frame.take(yielded=True)
                    yield value
            finally:
                value = None
        return native_generator()

    def _effect(self):
        op, destinations, args, raw, vector = self._parts()
        if op == 13 and raw == (4,):
            if len(destinations) != 4 or len(args) != 1 or vector:
                raise VerificationUnknown('verification four-value unpack ABI differs')
            first, second, third, fourth = self._get(args[0])
            self._set(destinations[0], first)
            self._set(destinations[1], second)
            self._set(destinations[2], third)
            self._set(destinations[3], fourth)
            first = second = third = fourth = None
            return 0
        if op == 19:
            if len(raw) != 2 or args or vector or len(destinations) != 1:
                raise VerificationUnknown('verification import ABI differs')
            key = tuple(self.image.literal(i) for i in raw)
            if key == ('hia_program_native', 'validate_block_layout_plan'):
                from .hia_program_native import validate_block_layout_plan
                self._set(destinations[0], validate_block_layout_plan)
            elif key == ('hia_program_native', 'emit_program_machine'):
                from .hia_program_native import emit_program_machine
                self._set(destinations[0], emit_program_machine)
            elif key == ('hia_checker_identity', 'checker_native_selection'):
                from .hia_checker_identity import checker_native_selection
                self._set(destinations[0], checker_native_selection)
            elif key == ('hia_machine_plan', 'preservation_checks'):
                from .hia_machine_plan import preservation_checks
                self._set(destinations[0], preservation_checks)
            elif key == ('hia_safe_core_elf', 'bind_final_artifact'):
                from .hia_safe_core_elf import bind_final_artifact
                self._set(destinations[0], bind_final_artifact)
            else:
                raise VerificationUnknown('verification import is outside the fixed inventory')
            return 0
        if op == 21:
            if len(args) != 1 or destinations or raw or vector:
                raise VerificationUnknown('verification exception-match ABI differs')
            return _match_exception(self, args[0])
        return super()._effect()

    def service(self, issued):
        # Same issued-object/native-preclaim protocol as the frozen Plan
        # engine. The additional flag prevents a failing physical exception
        # mechanism from being acknowledged as a known foreign policy error.
        if (self.closed and not self._retiring) or issued is not self.pending or type(issued) is not Issued:
            raise VerificationUnknown('verification observation is not the issued permission')
        if type(issued.raw) is not bytes or issued.raw != self.frame_bytes or self.executed:
            raise VerificationUnknown('verification observation changed or was consumed')
        self.executed = True
        try:
            if self._invoke(2, op=_read_word(issued.raw, 32)) != 4:
                raise VerificationUnknown('verification observation claim refused')
            observed = _capture_with_handler(self)
            if self._uncertain:
                if not observed[0]:
                    raise observed[1]
                raise VerificationUnknown('verification physical effect lost its outcome')
            if observed[0]:
                self.reply = (observed[1], 0)
            else:
                self.error = observed[1]
                self.reply = (0, 1)
            observed = None
            self.completed = True
        except BaseException:
            self._uncertain = True
            self.close(release=False)
            raise


class NativeVerificationImage(NativeMachinePlanControl):
    def __init__(self, image, expected_sha256, namespace=None):
        try:
            super().__init__(image, expected_sha256)
            self._bind_namespace(namespace)
        except BaseException:
            self._entry = None
            for resource in (getattr(self, '_delivery', None), getattr(self, '_mapping', None)):
                if resource is not None:
                    try:
                        resource.close()
                    except BaseException:
                        _UNCONFIRMED_IMAGE_CLEANUP.append((self, resource))
            raise

    def _bind_namespace(self, namespace):
        _load_foreign_ports()
        if namespace is None:
            from . import hia_agent_service
            namespace = vars(hia_agent_service)
        if type(namespace) is not dict:
            raise TypeError('verification requires the actual service global namespace')
        self.namespace = namespace
        self.modes = {name: (number, arity) for number, (name, arity) in enumerate(ARITIES.items(), 1)}
        if self.function_count != len(ARITIES) + 1:
            raise VerificationUnknown('complete verification function inventory differs')
        for mode, arity in self.modes.values():
            if self.function(mode)[2] != arity:
                raise VerificationUnknown('verification method argument ABI differs')
        if self.function(8)[2] & 0xffff != 1 or not self.function(8)[2] & (1 << 16):
            raise VerificationUnknown('verification lazy generator ABI differs')

    def prepare(self, name, arguments, captures=(), *, witness=None):
        mode, arity = self.modes[name]
        if type(arguments) is not tuple or len(arguments) != arity or captures:
            raise VerificationUnknown('verification bound argument count differs')
        return VerificationFrame(self, mode, arguments, witness=witness)

    def run(self, name, *arguments):
        frame = self.prepare(name, arguments)
        arguments = None
        return self.finish(frame)


class NativeVerificationService:
    """An immutable held image/custody scope; no Python reference to service."""
    def __init__(self, image, *, checker_custody=None):
        if type(image) is not NativeVerificationImage:
            raise TypeError('verification service requires its actual admitted image')
        self.image, self.custody, self.closed = image, checker_custody, False

    def checker_owner(self):
        if self.custody is None:
            raise VerificationUnknown('verification owner lacks actual captured checker custody')
        return self.custody

    def prepare(self, name, arguments):
        if self.closed:
            raise VerificationUnknown('verification service is closed for new work')
        return self.image.prepare(name, arguments)

    def finish(self, frame):
        if self.closed:
            raise VerificationUnknown('verification service is closed for new work')
        token = _ACTIVE.set(self)
        try:
            return self.image.finish(frame)
        finally:
            _ACTIVE.reset(token)


def active_verification():
    return _ACTIVE.get()

"""Fixed foreign-object bridge for the HIA structural resource controller.

Graph traversal, profile membership, numeric comparisons, limits, error choice
and every receipt field are in the selected HIA image. The bridge executes
only its issued, once-only physical/object continuations. Complete Python
objects are opaque identities; their semantic contents are never preplanned.
"""
from __future__ import annotations

import ctypes
from dataclasses import dataclass
from hashlib import sha256
import json
import mmap
import os
import struct
import sys

from .hia_instruction_policy_native import transport
from .hia_json_preflight_native import NativeHiaJsonImage, _installed_json_image, _source_resource_path
from .hia_native_value_graph import NativeObjectPool, decode_bound_native_graph

SOURCE = _source_resource_path('examples/hia_bootstrap/static_budget.hepta')
SCHEMA = 'hepta.hia.static-budget-native.v1'
SELECTOR = 'HEPTA_HIA_STATIC_BUDGET_MANIFEST'
MAGIC = int.from_bytes(b'HIABUD01', 'little')
ABI = 0xfffffff1
BASE = 8192
MASK = (1 << 64) - 1
QUERIES = frozenset((7, 11, 12, 13, 15))
REQUESTS = frozenset((*range(1, 18), 100, 101))
EMPTY = transport(None)
POLICY_KEYS = ('max_allocator_interactions', 'max_vm_ticks', 'max_call_depth',
               'max_live_heap_bytes')


def rejected(detail):
    from .hia_static_budget import HIAStaticBudgetRejected
    raise HIAStaticBudgetRejected('E_HIA_BUDGET_NATIVE', 'native structural transport: ' + detail)


def _pointer(value):
    return ctypes.addressof(ctypes.c_char.from_buffer(value)) if len(value) else 0


def _metadata(value):
    typ = type(value)
    if value is None:
        return [0, 0, 0, 0]
    if typ is bool:
        return [1, 0, 0, int(value)]
    if typ is int:
        return [2, int(value < 0), value.bit_length(), value & MASK]
    if typ is str:
        return [4, 0, 0, 0]
    if typ is list:
        return [5, 0, 0, 0]
    if typ is dict:
        return [6, 0, 0, 0]
    return [7, 0, 0, 0]


def _binary_integer(value):
    if type(value) is not int:
        rejected('binary object is not an exact integer')
    negative = value < 0
    magnitude = -value if negative else value
    raw = magnitude.to_bytes((magnitude.bit_length() + 7) // 8, 'little')
    return struct.pack('<2Q', 12, 1 + len(raw)) + bytes((int(negative),)) + raw


@dataclass(frozen=True)
class BudgetFrame:
    sequence: int
    request: int
    words: tuple[int, int, int, int]
    status: int
    value: object


class BudgetContext:
    """Per-invocation opaque custody and non-replayable foreign permissions."""
    def __init__(self, mode, program=None, limits=(None, None, None, None), *,
                 policy=None, document=None, schema=None, allow_chain=False):
        self.closed = False
        self.workspace = self.output = None
        self._created_arena = self._previous_arena = None
        self._created_output = self._previous_output = None
        self.pool = NativeObjectPool()
        self.input = self.source_wire = None
        self.pending = self.terminal = self.binding = None
        self.fields = None
        self.sequence = self.executed = self.completed = 0
        self.accepted = False
        self.cleanup_error = None
        try:
            none_id = self.pool.add(None)
            program_id = self.pool.add(program)
            limit_ids = [self.pool.add(value) for value in limits]
            policy_id = self.pool.add(policy)
            expected = {'max_allocator_interactions', 'max_vm_ticks', 'max_call_depth',
                        'max_live_heap_bytes'}
            expected_id = self.pool.add(expected)
            literal_ids = [self.pool.add(key) for key in POLICY_KEYS]
            raw = transport([mode, program_id, limit_ids, policy_id, expected_id,
                             none_id, schema, int(allow_chain), document, literal_ids])
            self.workspace = mmap.mmap(-1, max(1 << 20, (BASE + len(raw) + 4095) & ~4095))
            self.output = mmap.mmap(-1, 1 << 16)
            self.input = bytearray(raw)
            self.source_wire = raw
        except BaseException:
            self._close_preserving_error()
            raise

    def close(self, *, release_objects=True):
        self.closed = True
        self.pending = self.terminal = self.binding = self.fields = None
        self.input = self.source_wire = None
        first = None
        for name in ('_created_arena', '_previous_arena', 'workspace',
                     '_created_output', '_previous_output', 'output'):
            arena = getattr(self, name)
            if arena is not None:
                try:
                    arena.close()
                    setattr(self, name, None)
                except BaseException as exc:
                    if first is None:
                        first = exc
        if release_objects:
            try:
                self.pool.clear()
            except BaseException as exc:
                if first is None:
                    first = exc
        self.cleanup_error = first
        if first is not None:
            raise first

    def _close_preserving_error(self):
        try:
            # Original Python locals remain alive in a retained exception
            # traceback. Keep still-live foreign identities with this context;
            # only explicitly completed temporaries were already released.
            # Owned arenas and all execution permissions close immediately.
            self.close(release_objects=False)
        except BaseException:
            pass

    def _grow(self, needed, *, output=False):
        name = 'output' if output else 'workspace'
        created = '_created_output' if output else '_created_arena'
        previous = '_previous_output' if output else '_previous_arena'
        current = getattr(self, name)
        if type(needed) is not int or needed <= len(current):
            rejected('growth request does not increase an arena')
        size = (max(needed, len(current) * 2) + 4095) & ~4095
        setattr(self, created, mmap.mmap(-1, size))
        ctypes.memmove(_pointer(getattr(self, created)), _pointer(current), len(current))
        setattr(self, previous, current)
        setattr(self, name, getattr(self, created))
        setattr(self, created, None)
        getattr(self, previous).close()
        setattr(self, previous, None)

    @staticmethod
    def _fields(frame):
        if (type(frame) is not BudgetFrame or type(frame.sequence) is not int
                or type(frame.request) is not int or type(frame.status) is not int
                or type(frame.words) is not tuple or len(frame.words) != 4
                or any(type(value) is not int for value in frame.words)):
            rejected('issued frame has a changed exact representation')
        return (frame.sequence, frame.request, frame.words, frame.status)

    def _check(self, frame, *, terminal):
        if (self.closed or frame is not (self.terminal if terminal else self.pending)
                or self._fields(frame) != self.fields):
            rejected('frame is not the current exact issued result')
        if self.binding is not None:
            try:
                self.binding.validate(frame.value)
            except (ValueError, TypeError) as exc:
                rejected('issued graph changed: ' + str(exc))
        elif frame.value is not None:
            rejected('empty continuation payload changed')

    def service(self, frame):
        try:
            self._check(frame, terminal=False)
            if frame.sequence != self.sequence or self.executed == self.sequence:
                rejected('foreign permission has already been consumed')
            self.executed = self.sequence
            self.pending = None
            raw = self._invoke(frame)
            if raw is not None:
                used = struct.unpack_from('<Q', self.workspace, 64)[0]
                needed = (used + len(raw) + 7) & ~7
                if needed > len(self.workspace):
                    self._grow(needed)
                self.input = bytearray(raw)
                self.source_wire = raw
            struct.pack_into('<Q', self.workspace, 88, frame.sequence)
            self.completed = frame.sequence
            self.binding = self.fields = None
        except BaseException:
            self._close_preserving_error()
            raise

    def _invoke(self, frame):
        request = frame.request
        a, b, _c, _d = frame.words
        pool = self.pool
        value = frame.value
        if request == 100:
            self._grow(a)
            return None
        if request == 101:
            self._grow(a, output=True)
            return None
        if request == 1:
            result = _metadata(pool.get(a))
        elif request == 2:
            from .hia_program import verify_program
            checked = verify_program(pool.get(a))
            result = [pool.add(checked), checked.as_dict(), checked.structured_bytes is not None if b else False]
        elif request == 3:
            result = pool.add(pool.get(a).copy())
        elif request == 4:
            result = pool.add(set(pool.get(a)))
        elif request == 5:
            result = pool.get(a) != pool.get(b)
        elif request == 6:
            result = pool.add(iter(pool.get(a).values()))
        elif request == 7:
            result = pool.add(pool.get(a)[value])
        elif request == 8:
            return _binary_integer(pool.get(a))
        elif request == 9:
            checked = pool.get(a)
            result = [checked.sha256, checked.input_sha256 if b else None]
        elif request == 10:
            from .hia_heap_bound import analyze_constant_live_heap
            result = pool.add(analyze_constant_live_heap(pool.get(a)))
        elif request == 11:
            from .hia_heap_bound import qualify_entry_live_heap_budget
            result = pool.add(qualify_entry_live_heap_budget(pool.get(a), value,
                                                           max_live_heap_bytes=pool.get(b)))
        elif request == 12:
            ident = pool.add(value)
            raw = json.dumps(value, sort_keys=True, separators=(',', ':'),
                             ensure_ascii=False, allow_nan=False).encode('utf-8')
            result = [ident, sha256(raw).hexdigest()]
        elif request == 13:
            pool.get(a)[value[0]] = value[1]
            result = None
        elif request == 14:
            try:
                item = next(pool.get(a))
            except StopIteration:
                result = [True, 0]
            else:
                result = [False, pool.add(item)]
        elif request == 15:
            result = pool.add(value)
        elif request == 16:
            result = pool.add(iter(pool.get(a)))
        elif request == 17:
            pool.release(a)
            result = None
        else:
            rejected('unrecognized foreign request')
        return transport(result)

    def accept(self, frame):
        try:
            self._check(frame, terminal=True)
            if self.accepted or frame.request:
                rejected('terminal permission has already been consumed')
            self.accepted = True
            if frame.status == 2:
                if (type(frame.value) is not list or len(frame.value) != 2
                        or any(type(value) is not str for value in frame.value)):
                    rejected('semantic refusal has an invalid representation')
                from .hia_static_budget import HIAStaticBudgetRejected
                raise HIAStaticBudgetRejected(*frame.value)
            return frame.value
        except BaseException:
            self._close_preserving_error()
            raise


class NativeStaticBudget(NativeHiaJsonImage):
    def step(self, context):
        try:
            if (context.closed or context.pending is not None or context.terminal is not None
                    or context.completed != context.sequence):
                rejected('closed or incomplete context cannot enter the image')
            returned = self._entry(_pointer(context.input), len(context.input),
                _pointer(context.output), len(context.output),
                _pointer(context.workspace), len(context.workspace))
            if bytes(context.input) != context.source_wire:
                rejected('immutable foreign reply/source bytes changed')
            if returned == ABI:
                rejected('HIA ABI refused its private representation')
            words = struct.unpack_from('<16Q', context.workspace)
            magic, _phase, sequence, request, a, b, c, d = words[:8]
            status, length = words[12:14]
            if (magic != MAGIC or sequence != context.sequence + 1 or returned != request
                    or request not in REQUESTS | {0} or status not in (0, 1, 2)
                    or bool(request) == bool(status) or length > len(context.output)
                    or request and request not in QUERIES and length):
                rejected('native result header differs')
            if request and (c or d or (request in (2, 9) and b not in (0, 1))
                    or (request not in (2, 5, 9, 11) and b)):
                rejected('foreign request words are not canonical')
            value = binding = None
            if length:
                value, binding = decode_bound_native_graph(bytes(context.output[:length]), EMPTY,
                    binary_integers=True, objects=context.pool, extent_bounds=True)
            elif status or request in QUERIES:
                rejected('native result omitted its complete graph')
            frame = BudgetFrame(sequence, request, (a, b, c, d), status, value)
            context.sequence = sequence
            context.fields = context._fields(frame)
            context.binding = binding
            if request:
                context.pending = frame
            else:
                context.terminal = frame
            return frame
        except BaseException:
            context._close_preserving_error()
            raise

    def _run(self, *args, **kwargs):
        context = BudgetContext(*args, **kwargs)
        try:
            while True:
                frame = self.step(context)
                if frame.request:
                    context.service(frame)
                else:
                    return context.accept(frame)
        finally:
            if sys.exc_info()[0] is None:
                context.close()
            else:
                context._close_preserving_error()

    def qualify_vm_call_depth(self, program, *, max_call_depth):
        return self._run(1, program, (None, None, max_call_depth, None))

    def analyze_static_budget(self, program, *, max_allocator_interactions=None,
                              max_vm_ticks=None, max_call_depth=None, max_live_heap_bytes=None):
        return self._run(2, program, (max_allocator_interactions, max_vm_ticks,
                                     max_call_depth, max_live_heap_bytes))

    def qualify_bounded_resources(self, program, *, limits):
        return self._run(3, program, policy=limits)

    def audit_resource_profile(self, document, *, schema, allow_chain):
        return self._run(4, document=document, schema=schema, allow_chain=allow_chain)


def installed_static_budget(path):
    return _installed_json_image(path, SOURCE, SCHEMA, NativeStaticBudget)


def selected_static_budget():
    path = os.environ.get(SELECTOR)
    if not path:
        return None
    # A selected composed owner captures all four paths before any image
    # admission or foreign program callback. The cached image stays immutable.
    heap_paths = (os.environ.get('HEPTA_HIA_HEAP_BOUND_MANIFEST'),
                  os.environ.get('HEPTA_HIA_HEAP_LIVE_ENGINE_MANIFEST'), path,
                  os.environ.get('HEPTA_HIA_HEAP_PAYLOAD_MANIFEST'))
    try:
        image = installed_static_budget(path)
        if not heap_paths[0]:
            return image
        from .hia_heap_bound_native import compose_static_heap
        return compose_static_heap(image, heap_paths)
    except (ValueError, OSError, UnicodeError, RuntimeError) as exc:
        from .hia_static_budget import HIAStaticBudgetRejected
        raise HIAStaticBudgetRejected('E_HIA_BUDGET_NATIVE',
                                     'selected native structural image refused: ' + str(exc)) from exc

"""HIA-owned task helper cache and exact generator continuation order.

The bridge transports HIA-issued type identities, executes only requested
continuations and materializes complete native state deltas. Cache lookup,
miss ordering, prefix commits, refusal and helper publication belong to HIA.
"""
from __future__ import annotations

import ctypes
from dataclasses import dataclass
import os
import secrets
import struct

from .hia_composite_types_native import _NativeTypeIdentity
from .hia_instruction_policy_native import transport
from .hia_json_preflight_native import NativeHiaJsonImage, _installed_json_image, _source_resource_path
from .hia_native_value_graph import NativeValuePool, decode_bound_native_graph
from .hia_program import HIAProgramRejected
from .hia_task_helpers_native import ERRORS as HELPER_ERRORS

SOURCE = _source_resource_path('examples/hia_bootstrap/task_helper_cache.hepta')
SCHEMA = 'hepta.hia.task-helper-cache-native.v1'
SELECTOR = 'HEPTA_HIA_TASK_HELPER_CACHE_MANIFEST'
MAGIC = int.from_bytes(b'HIATHC01', 'little')
INPUT_BYTES = 1 << 20
OUTPUT_BYTES = 4096
WORKSPACE_BYTES = 2 << 20
ERRORS = {**HELPER_ERRORS,
    4: ('E_HIA_TYPE', 'selected native function requires native task helper generation'),
    5: ('E_HIA_TYPE', 'selected native task helper cache requires native task helper generation')}


def _reject(message):
    raise HIAProgramRejected('native task helper cache transport: ' + message, 'E_HIA_TYPE')


class HelperCacheContext:
    """One invocation; the owner's cache persists across invocations/functions."""
    def __init__(self, owner, typ, operation, *, require_native=False):
        self.owner, self.typ, self.operation = owner, typ, operation
        key = typ.key
        if type(key) is not _NativeTypeIdentity:
            _reject('selected cache requires HIA-issued type identities')
        self.nonce, self.type_id = key.session, key.identifier
        self.keys = {}
        self.pool = NativeValuePool()
        rows = []
        for (held_key, held_operation), name in tuple(owner.helper_names.items()):
            identifier = self.identity(held_key)
            rows.append([identifier, held_operation, name, self.pool.add(name)])
        self.identity(key)
        self.metadata = [self.type_id, operation, require_native, rows, secrets.token_hex(16)]
        self.metadata_bytes = transport(self.metadata)
        self.inventory, self.functions = None, ()
        self.generator = self.step_type = self.generated = None
        self.effects = [None, None]
        self.reply, self.sequence = None, 0
        self.executed = self.completed = 0
        self.pending = None
        self.terminal = None
        self._issued = self._binding = self._issued_fields = None
        self.closed = self.released = self.committed = False
        self.output = self.workspace = None
        try:
            self.output = ctypes.create_string_buffer(OUTPUT_BYTES)
            self.workspace = ctypes.create_string_buffer(WORKSPACE_BYTES)
        except BaseException:
            self.close()
            raise

    def identity(self, key):
        if (type(key) is not _NativeTypeIdentity or key.session is not self.nonce
                or type(key.identifier) is not int or not 0 < key.identifier <= 0xffffffff):
            _reject('type identity is outside the held HIA session')
        self.keys[key.identifier] = key
        return key.identifier

    def close(self):
        self.closed = self.released = True
        self._binding = None
        self.output = self.workspace = None

    def data(self):
        if self.closed:
            _reject('closed helper cache context cannot resume')
        if transport(self.metadata) != self.metadata_bytes:
            _reject('held cache metadata changed')
        return transport([self.metadata, self.sequence, self.owner.serial, self.reply, self.inventory])

    def service(self, request, query):
        if (self.closed or self.pending is None or self.executed >= self.sequence
                or type(request) is not int or request != self.pending[0]
                or query is not self.pending[1]):
            _reject('callback is not the current unexecuted continuation')
        try:
            self._validate(self._issued)
            self.executed = self.sequence
            self._service(request, query)
            self.completed = self.sequence
            self.pending = None
        except BaseException:
            self.close()
            raise

    def _validate(self, result):
        if (result is not self._issued or self._binding is None
                or any(type(value) is not int for value in (result.error, result.request, result.sequence))
                or (result.error, result.request, result.sequence) != self._issued_fields):
            _reject('result is not the current issued native frame')
        try:
            self._binding.validate(result.value)
        except ValueError as error:
            _reject('issued graph changed: ' + str(error))

    def _service(self, request, query):
        fields = {1: set(), 2: set(), 3: set(), 4: {'index', 'slot'},
                  5: {'serial'}, 6: {'key'}}
        if request not in fields or type(query) is not dict or set(query) != fields[request]:
            _reject('continuation is not a complete object')
        if request == 1:
            from .hia_task_helpers_native import selected_task_helpers
            self.generator = selected_task_helpers()
            self.reply = self.generator is not None
        elif request == 2:
            native_types = self.owner.native_types
            if native_types is None or native_types._nonce is not self.nonce:
                _reject('selected cache requires the native task protocol owner')
            # Hold the already owned type session; the default wrapper cannot
            # reselect a hosted task check between admission and invocation.
            self.step_type = native_types.check_task(self.typ, self.owner.signatures)
            self.reply = None
        elif request == 3:
            self.functions = tuple(self.owner.functions.items())
            self.inventory = [self.typ.poll, self.typ.cancel, [name for name, _ in self.functions]]
            self.reply = None
        elif request == 4:
            index, slot = query['index'], query['slot']
            if (type(index) is not int or not 0 <= index < len(self.functions)
                    or type(slot) is not int or slot not in (0, 1)):
                _reject('effect reference is outside the held function inventory')
            self.effects[slot] = self.functions[index][1]['effects']
            self.reply = None
        elif request == 5:
            serial = query['serial']
            if (type(serial) is not int or not 0 <= serial <= 8192
                    or self.generator is None or self.step_type is None):
                _reject('generator continuation lacks admitted dependencies')
            result = self.generator.generate(self.typ, self.step_type, self.operation, serial, *self.effects)
            self.generated = result
            name_id = self.pool.add(result.name)
            helper_id = self.pool.add(result.helper)
            self.reply = [result.serial, result.error, result.name, name_id, helper_id]
        else:
            if type(query['key']) is not str:
                _reject('missing function key is not a string')
            raise KeyError(query['key'])

    def commit(self, result):
        if (self.released or self.committed or self.terminal is None
                or result is not self.terminal):
            _reject('terminal result is not the current uncommitted result')
        # Claim before the first owner write: an interrupted prefix is never
        # replayable, including when the original exception keeps this context.
        try:
            self._validate(result)
            self.committed = True
            value = result.value
            for serial in value['serial']:
                self.owner.serial = serial
            for identifier, operation, name in value['cache']:
                self.owner.helper_names[(self.keys[identifier], operation)] = name
            result.admit()
            for helper in value['helpers']:
                self.owner.helpers.append(helper)
            return value['name']
        except BaseException:
            self.close()
            raise


@dataclass(frozen=True)
class HelperCacheResult:
    error: int
    request: int
    sequence: int
    value: dict

    def admit(self):
        if self.error:
            code, message = ERRORS[self.error]
            raise HIAProgramRejected(message, code)


class NativeTaskHelperCache(NativeHiaJsonImage):
    def lower(self, owner, typ, operation, *, require_native=False):
        context = HelperCacheContext(owner, typ, operation, require_native=require_native)
        try:
            for _ in range(16):
                result = self.step(context)
                if result.request:
                    context.service(result.request, result.value)
                else:
                    return context.commit(result)
            _reject('controller did not complete within its fixed continuation bound')
        finally:
            context.close()

    def step(self, context):
        if context.closed:
            _reject('closed helper cache context cannot resume')
        if context.pending is not None or context.completed != context.sequence:
            _reject('previous helper cache continuation has not completed')
        try:
            return self._step(context)
        except BaseException:
            context.closed = True
            raise

    def _step(self, context):
        wire = context.data()
        if len(wire) > INPUT_BYTES:
            _reject('input exceeds private byte capacity')
        source = ctypes.create_string_buffer(wire, max(1, len(wire)))
        extent = self._entry(source, len(wire), context.output, OUTPUT_BYTES,
                             context.workspace, WORKSPACE_BYTES)
        if ctypes.string_at(source, len(wire)) != wire:
            _reject('input bytes changed')
        if type(extent) is not int or not 88 <= extent <= OUTPUT_BYTES:
            _reject('invalid result extent/status ' + str(extent))
        magic, error, request, size, sequence, r0, r1, r2 = struct.unpack_from('<8Q', context.output)
        if (magic != MAGIC or error not in {0, *ERRORS} or request > 6 or error and request
                or r0 or r1 or r2 or size != extent - 64 or sequence != context.sequence + 1):
            _reject('invalid controller frame/sequence correlation')
        try:
            encoded = ctypes.string_at(ctypes.addressof(context.output) + 64, size)
            value, binding = decode_bound_native_graph(encoded, wire, external=context.pool)
            if type(value) is not dict:
                raise ValueError('result is not a complete object')
            if not request:
                if set(value) != {'serial', 'cache', 'helpers', 'name'}:
                    raise ValueError('result state fields differ')
                if any(type(value[key]) is not list or len(value[key]) > 1
                       for key in ('serial', 'cache', 'helpers')):
                    raise ValueError('result state arrays differ')
                if any(type(item) is not int or not 0 <= item <= 8192 for item in value['serial']):
                    raise ValueError('result serial is outside the held counter')
                for row in value['cache']:
                    if (type(row) is not list or len(row) != 3 or type(row[0]) is not int
                            or row[0] != context.type_id or row[1] != context.operation
                            or type(row[2]) is not str):
                        raise ValueError('result cache row is outside the held request')
                if value['name'] is not None and type(value['name']) is not str:
                    raise ValueError('result name is not a held string/null')
                if error and value['helpers'] or any(type(item) is not dict for item in value['helpers']):
                    raise ValueError('result helper publication differs')
        except (ValueError, TypeError, KeyError, UnicodeError, RecursionError, OverflowError) as exc:
            _reject('invalid complete object graph: ' + str(exc))
        result = HelperCacheResult(error, request, sequence, value)
        context._issued = result
        context._binding = binding
        context._issued_fields = (error, request, sequence)
        context.sequence = sequence
        context.pending = (request, value) if request else None
        if not request:
            context.closed = True
            context.terminal = result
        return result


def installed_task_helper_cache(manifest):
    return _installed_json_image(manifest, SOURCE, SCHEMA, NativeTaskHelperCache)


def selected_task_helper_cache():
    manifest = os.environ.get(SELECTOR)
    if not manifest:
        return None
    try:
        return installed_task_helper_cache(manifest)
    except (ValueError, OSError, UnicodeError, RuntimeError) as exc:
        raise HIAProgramRejected('selected native task helper cache refused: ' + str(exc), 'E_HIA_TYPE') from exc
